from pathlib import Path
import json,re,html
ROOT=Path(__file__).parent; D=ROOT/'dist'; DATA=D/'data'
brief=(ROOT/'content/brief.md').read_text()
def save(name,obj):
 target=DATA/(name+'.json')
 if name=='config' and target.exists(): return
 target.write_text(json.dumps(obj,indent=2))
def esc(s): return html.escape(str(s))
def blocks(prefix):
 result=[]
 for match in re.finditer(r'## '+prefix+r' (\d+) — ([^\n]+)\n(.*?)(?=\n## |\n# |\Z)',brief,re.S):
  title=match[2].title(); raw=match[3]; secs={}
  for m in re.finditer(r'### ([^\n]+)\n(.*?)(?=\n### |\Z)',raw,re.S):
   text=m[2].strip().strip('-').strip(); text=re.sub(r'\*\*','',text)
   text=text.replace('Include grade-level details in structured technical tables after engineering review.','Grade-level details require engineering review before procurement.')
   if m[1]!='Design': secs[m[1]]=text
  result.append(dict(name=title,sections=secs))
 return result
