def prose(text):return ''.join('<p>'+esc(p.replace('\n',' '))+'</p>' for p in text.split('\n\n') if p.strip())
def structured_sections(sections):
 result=''
 for title,text in sections.items():
  lines=[x.strip('- ').strip() for x in text.split('\n') if x.strip()]
  if title=='Technical data structure':continue
  result+='<section class="data-section"><h2>'+esc(title)+'</h2>'
  if any(len(x)>160 for x in lines):result+=prose(text)
  else:result+='<ul class="technical-list">'+''.join('<li>'+esc(x)+'</li>' for x in lines)+'</ul>'
  result+='</section>'
 return result
