body=intro('Material Intelligence','The right material. By design.','Explore published material references and related product categories. A clearer starting point for your technical enquiry.','MATERIAL INTELLIGENCE')+'<section class="material-explorer"><div class="material-options" role="tablist" aria-label="Material families" aria-orientation="vertical">'+''.join(f'<button role="tab" id="material-tab-{i}" data-material="{i}" aria-selected="{str(i==0).lower()}" aria-controls="material-panel" tabindex="{0 if i==0 else -1}">{m["name"]}</button>' for i,m in enumerate(materials))+'</div><div id="material-panel" role="tabpanel" aria-labelledby="material-tab-0"><div class="material-swatch"></div><div id="material-copy"><h2>Carbon Steel</h2><p>'+materials[0]['overview']+'</p></div></div></section><section class="narrow-section"><p class="review-note">Grade references do not confirm availability in every product form. Entries without published technical data are deliberately left unspecified. Engineering review is required before procurement.</p></section>'+cta();page('/materials/','Material Intelligence',body)
def field(name,label_,required=False,type_='text',full=False):return '<div class="field '+('full' if full else '')+'"><label for="'+name+'">'+label_+(' <span aria-label="required">*</span>' if required else '')+'</label><input id="'+name+'" name="'+name+'" type="'+type_+'" '+('required' if required else '')+' maxlength="'+('254' if type_=='email' else '200')+'" autocomplete="'+({'email':'email','phone':'tel','company':'organization','contact':'name','name':'name','country':'country-name'}.get(name,'off'))+'"></div>'
body=intro('Request a Quote','Your project. Let’s connect.','Build a multi-product enquiry with the details that matter. Your selected products stay with you as you explore.','PROJECT ENQUIRY')+'<section class="rfq-layout"><div><div class="draft-banner"><strong>Draft enquiry workspace</strong><p>Online delivery is not configured yet. Prepare and download your enquiry, then email it to '+link('mailto:'+company['email'],company['email'])+'. No submission will be reported as sent.</p></div><form id="rfq-form"><h2>Your required products</h2><div id="rfq-items"></div><div class="add-item-bar"><label for="add-category">Add a product category</label><select id="add-category">'+''.join('<option value="'+p['id']+'">'+p['name']+'</option>' for p in products)+'</select><button type="button" class="button secondary" id="add-item">Add product</button></div><h2>Company & project details</h2><div class="form-grid">'+field('company','Company name',True)+field('contact','Contact person',True)+field('email','Business email',True,'email')+field('phone','Phone',False,'tel')+field('country','Country',True)+field('project','Project name')+field('destination','Delivery destination',True)+field('requirements','Additional requirements',False,'text',True)+'</div><label for="documents">Project document (PDF, CSV, XLSX, DOCX; up to 10 MB)</label><input type="file" id="documents" name="document" accept=".pdf,.csv,.xlsx,.docx"><p class="small-note">Files are only transmitted when a backend is configured. Downloads contain the filename, not the document; attach it separately when emailing.</p><label class="consent"><input type="checkbox" name="consent" required> I understand the '+link('/privacy/','data notice')+' and consent to using these details to respond to this enquiry.</label><div class="form-actions"><button class="button" type="submit" id="rfq-submit">Download enquiry draft</button><button class="button secondary" type="button" id="clear-enquiry">Clear enquiry</button></div><p id="rfq-status" role="status" aria-live="polite"></p></form></div><aside class="rfq-aside"><p class="eyebrow">A BETTER TECHNICAL BRIEF</p><h3>Precision starts here.</h3><p>Include material, grade, standard, size, quantity, and your delivery destination.</p><p>All specifications and combinations remain subject to technical and commercial confirmation.</p>'+link('tel:+97144328439',company['phone'],'text-link')+link('mailto:'+company['email'],'Email our team','text-link')+'<p class="small-note">Product selections are stored on this browser. Contact details and documents are not saved locally.</p></aside></section>';page('/request-a-quote/','Request a Quote',body)
body=intro('Contact','Every connection starts with a conversation.','Share your requirements with our Dubai team.','GET IN TOUCH')+'<section class="contact-layout"><aside><h2>Dubai headquarters</h2><address>'+'<br>'.join(company['address'])+'</address>'+link('tel:+97144328439',company['phone'],'contact-link')+link('mailto:'+company['email'],company['email'],'contact-link')+'<div class="location-map"><span class="location-dot"></span><strong>JUMEIRAH LAKE TOWERS</strong><span>Jumeirah Business Center 4 · Dubai</span></div>'+link('https://www.google.com/maps/search/?api=1&query=Jumeirah+Business+Center+4+Dubai','Open location in Google Maps','text-link')+'<hr>'+button('/request-a-quote/','Build a product enquiry')+'</aside><div><h2>General enquiry</h2><p class="draft-banner">Online delivery is not configured. Download your message and email it to our team.</p><form id="contact-form"><div class="form-grid">'+field('name','Full name',True)+field('company','Company',True)+field('email','Business email',True,'email')+field('phone','Phone number',False,'tel')+field('country','Country',True)+field('subject','Subject',True)+'<div class="field full"><label for="message">Message *</label><textarea id="message" name="message" required rows="6" maxlength="10000"></textarea></div></div><label class="consent"><input type="checkbox" name="consent" required> I understand the '+link('/privacy/','data notice')+' and consent to using my details to respond to this enquiry.</label><button class="button" type="submit">Download message draft</button><p id="contact-status" role="status" aria-live="polite"></p></form></div></section>';page('/contact/','Contact',body)
body=intro('Privacy & Data Notice','Your data. Handled transparently.','This implementation notice describes how the current draft website works. Approved company legal content has not yet been provided.','PRIVACY')+'<section class="narrow-section"><h2>Privacy policy pending approval</h2><p>This page is not an approved legal privacy policy. The company must supply and approve legal content before a public launch or live enquiry collection.</p><h2>Browser storage</h2><p>The enquiry builder stores selected products and their technical requirements in localStorage on your device. Use “Clear enquiry” to remove them. Contact details and uploaded documents are not persisted by this website.</p><h2>Enquiry drafts</h2><p>With no backend configured, forms create a downloadable draft on your device. They do not transmit your enquiry to United Piping. Emailing a draft or following a telephone link uses your chosen service.</p><h2>External resources</h2><p>Core libraries and images are hosted with this website. External map and email links open third-party services only when selected. No analytics integration is included in this implementation.</p><h2>Questions</h2><p>Contact '+link('mailto:'+company['email'],company['email'])+' for company privacy enquiries.</p></section>';page('/privacy/','Privacy & Data Notice',body)
